//go:build ignore

// Generate a specialized packed traversal from the original state machine, so
// state/precedence/version parsing fixes have one maintained source of truth.
package main

import (
	"go/format"
	"os"
	"strings"
)

func main() {
	source, err := os.ReadFile("trie.go")
	if err != nil {
		panic(err)
	}
	s := string(source)
	start := strings.Index(s, "func (trie *RuneTrie) Get(")
	end := strings.Index(s, "// Put inserts")
	if start < 0 || end < start {
		panic("cannot find reference Get state machine")
	}
	s = s[start:end]
	dispatch := "\n\tif trie.compact != nil {\n\t\treturn trie.compact.get(key)\n\t}"
	if !strings.Contains(s, dispatch) {
		panic("cannot find compact dispatch")
	}
	s = strings.Replace(s, dispatch, "", 1)
	s = strings.Replace(s, "func (trie *RuneTrie) Get(key string) UserAgent {", "func (p *compactTrie) get(key string) UserAgent {", 1)
	s = strings.Replace(s, "node := trie", "var node uint32\n\tvar tail []rune", 1)
	s = strings.Replace(s, "// If result exists, we can append it to the value.", "if len(tail) > 0 {\n\t\t\t\tif tail[0] == r { tail = tail[1:] }\n\t\t\t\tcontinue\n\t\t\t}\n\n\t\t\t// If result exists, we can append it to the value.", 1)
	s = strings.Replace(s, "range node.result", "range p.resultsFor(node)", 1)
	start = strings.Index(s, "\t\t\t// Set the next node to the child of the current node.")
	if start < 0 {
		panic("cannot find node traversal")
	}
	end = strings.Index(s[start:], "\n\t\t}")
	if end < 0 {
		panic("cannot find traversal end")
	}
	s = s[:start] + "\t\t\tif next, label, ok := p.next(node, r); ok {\n\t\t\t\tnode, tail = next, label\n\t\t\t}" + s[start+end:]
	s = "// Code generated by go run generate_compact.go; DO NOT EDIT.\n\npackage useragent\n\nimport \"github.com/medama-io/go-useragent/internal\"\n\n" + s
	output, err := format.Source([]byte(s))
	if err != nil {
		panic(err)
	}
	if err := os.WriteFile("compact_get.go", output, 0644); err != nil {
		panic(err)
	}
}
